# number theory, freq table
def is_prime(n):
    if n%2 == 0 or n%3 == 0:
        return False
    for i in xrange(5, n, 6):
        if i*i > n:
            break
        if n%i == 0 or n%(i+2) == 0:
            return False
    return True  


