                    P[i] += 1
                if i+P[i] > R:
                    C, R = i, i+P[i]
            return P

        prefix = [0]*(len(nums)+1)
        for i in xrange(len(nums)):
            prefix[i+1] = prefix[i]+nums[i]
        p = manacher(nums)
        return max(prefix[(i+p[i])//2]-prefix[(i-p[i])//2] for i in xrange(1, len(p)-1))

